SELECT id, coupon_codes, items, ship_to, attributes, TRANSFORM(FILTER(items, x -> x.promo IS NOT NULL), x -> STRUCT(x.product_id AS pid, ROUND(x.price * 0.9, 2) AS discounted_price)) AS promo_lines, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'VIP')
